mapper.select:
SELECT id, course_name, course_code, description, credit, course_category,
       total_hours, teacher_id, course_status
FROM courses
WHERE teacher_id = #{teacherId}
AND course_name LIKE CONCAT('%', #{name}, '%')
AND course_code = #{courseCode}
AND course_category = #{category}
AND course_status = #{status}

SELECT COUNT(DISTINCT cs.student_id)
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.course_id = #{courseId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.course_id = #{courseId}
)

SELECT DISTINCT cs.student_id
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.course_id = #{courseId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.course_id = #{courseId}
)

SELECT DISTINCT cs.student_id
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.teacher_id = #{teacherId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.teacher_id = #{teacherId}
)

SELECT cs.student_id
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.course_id = #{courseId} AND cc.id = #{classId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.course_id = #{courseId} AND cc_c.class_id = #{classId}
)

SELECT COUNT(DISTINCT cs.student_id)
FROM class_students cs
WHERE cs.class_id IN (
    SELECT cc.id FROM course_classes cc WHERE cc.course_id = #{courseId} AND cc.id = #{classId}
    UNION
    SELECT cc_c.class_id FROM class_courses cc_c WHERE cc_c.course_id = #{courseId} AND cc_c.class_id = #{classId}
)

mapper.update:
UPDATE course_classes
SET course_id = #{courseId},
    teacher_id = #{teacherId},
    class_time = #{classTime},
    class_location = #{classLocation}
WHERE id = #{classId}
